# Final comprehensive sweep of paper/sage_sa.tex against the final calibration
# (10.00, 0.510, theta=0.005, ne=80). Written after discovering that the
# earlier two generators (stage5_paper_subs.py, stage5_paper_prose.py) left
# gaps: the abstract, introduction, calibration paragraph, proposition
# subsection, omega table, and take-up narrative still carried stage-4 or
# intermediate numbers, and in two places (GDP-B sign, take-up disequalising
# claim) the surrounding PROSE LOGIC was now factually wrong, not just the
# numbers. This script fixes both.
import re, sys
from pathlib import Path

S = Path(__file__).parent
R = {}
for l in (S/"sa_level4_results.txt").read_text().splitlines():
    if "\t" in l and not l.startswith("#"):
        k, v = l.split("\t"); R[k] = float(v)

def pct(x): return 100*x
def f1(x): return f"{x:.1f}"
def f2(x): return f"{x:.2f}"
def f3(x): return f"{x:.3f}"

r0, lo, hi = R["r0"], R["r0_lo"], R["r0_hi"]
gap = hi - lo
ratio0 = hi/lo

# omega table, read fresh
om = {}
for l in (S/"sa_omega_l4.txt").read_text().splitlines():
    m = re.match(r"^0\.(\d+)\s+\|\s+([\d.]+)\s+\|\s+([\d.]+)\s+\|\s+([\d.]+)\s+\|\s+([\d.]+)\s*/\s*([\d.]+)\s+\|\s+([\d.]+)\s+\|\s+([\d.]+)\s+\|\s+([\d.]+)\s+\|\s+([\d.]+)", l)
    if m:
        w = float("0."+m.group(1))
        om[w] = dict(kappa=float(m.group(2)), sigma=float(m.group(3)), rate=float(m.group(4)),
                     lo=float(m.group(5)), hi=float(m.group(6)), slope=float(m.group(7)),
                     sigbar=float(m.group(8)), ratio=float(m.group(9)), frontier=float(m.group(10)))
for w in (0.15, 0.30, 0.50):
    assert w in om, f"omega {w} row not parsed"

edits = []

# ---------------------------------------------------------------- abstract --
old_abs = "At the French moments the bound is $0.47$ against the dispersion of $0.75$ the participation data require, so the calibrated economy sits some sixty percent outside the coordination region, and the model's own numerical boundary at $0.30$ confirms the ordering with room to spare. Three results follow. The education gradient in participation divides roughly two to one between the taste for belonging and agency operating through wealth, the income effect beating the price of time, which is why participation rises with income although richer households face a higher opportunity cost of time. A budget-balanced make-work-pay subsidy has a direct effect of four percentage points and an equilibrium effect of eleven, from 35 percent participation to 11, so outside the multiplicity region the complementarity still amplifies policy by a factor of 2.5, and that factor is the reciprocal of one minus the very map slope the bound constrains, which ties the policy result to the theorem rather than leaving it a separate simulation. And a participation tax credit, the analogue of France's charitable-donations deduction and the United Kingdom's Gift Aid, moves participation the other way and by more, at a sixth of the fiscal cost, so two policies from the same pro-work family swap places between a GDP ledger and a GDP-B ledger."
new_abs = (f"At the French moments the bound is ${f2(R['sigbar'])}$ against the dispersion of ${f3(R['sigma'])}$ the participation data require, so the calibrated economy sits about ten percent outside the coordination region, and the model's own numerical boundary at ${f2(R['frontier'])}$ confirms the ordering. Three results follow. The education gradient in participation divides roughly two to one between the taste for belonging and agency operating through wealth, the income effect beating the price of time, which is why participation rises with income although richer households face a higher opportunity cost of time. A budget-balanced make-work-pay subsidy has a direct effect of {f1(pct(r0-R['r_sub_direct']))} percentage points and an equilibrium effect of {f1(pct(r0-R['r_sub']))}, from {f1(pct(r0))} percent participation to {f1(pct(R['r_sub']))}, so at this margin the complementarity amplifies policy by a factor of {f1(R['amp'])} at the size of shock examined, against a small-shock prediction of {f1(1/(1-R['slope0']))} from the reciprocal of one minus the very map slope the bound constrains, which ties the policy result to the theorem rather than leaving it a separate simulation. And a participation tax credit, the analogue of France's charitable-donations deduction and the United Kingdom's Gift Aid, moves participation the other way and by more, at a fraction of the fiscal cost, and remains equalising across every take-up rate examined, so two policies from the same pro-work family swap places between a GDP ledger and a GDP-B ledger.")
edits.append((old_abs, new_abs))

# ------------------------------------------------------------- introduction --
old_i1 = "At the French moments the bound is $0.47$ while the participation data require $0.75$, so the economy sits some sixty percent outside the coordination region, and because the threshold version overstates the true slope the conclusion is conservative. Scanning the full model puts its actual boundary at $0.30$, comfortably inside the analytical bound, as it must be."
new_i1 = (f"At the French moments the bound is ${f2(R['sigbar'])}$ while the participation data require ${f3(R['sigma'])}$, so the economy sits about ten percent outside the coordination region, and because the threshold version overstates the true slope the conclusion is conservative. Scanning the full model puts its actual boundary at ${f2(R['frontier'])}$, inside the analytical bound, as it must be.")
edits.append((old_i1, new_i1))

old_i2 = "Third, the activation-policy result of the companion paper is amplified on the participation margin, and the amplification is not a free parameter. A budget-balanced 20 percent make-work-pay subsidy raises the return to market hours and taxes everyone a lump sum to pay for it; both push against the time commitment. The direct effect, holding everyone else's participation fixed, is a fall of four percentage points. The equilibrium effect is a fall of eleven, from 35 percent participation to 25: the social feedback multiplies the direct effect by two and a half, because each household's exit lowers the belonging return of every other household. The multiplier is $1/(1-G')$ at the equilibrium, so the same slope the bound of the first result constrains is the slope that sets the size of the second. A flat enough map to rule out coordination traps is a map that still amplifies policy by a factor near two and a half, and the two statements are one statement."
new_i2 = (f"Third, the activation-policy result of the companion paper is sharply amplified on the participation margin, and the amplification is not a free parameter. A budget-balanced 20 percent make-work-pay subsidy raises the return to market hours and taxes everyone a lump sum to pay for it; both push against the time commitment. The direct effect, holding everyone else's participation fixed, is a fall of {f1(pct(r0-R['r_sub_direct']))} percentage points. The equilibrium effect is a fall of {f1(pct(r0-R['r_sub']))}, from {f1(pct(r0))} percent participation to {f1(pct(R['r_sub']))}: the social feedback multiplies the direct effect by {f1(R['amp'])}, because each household's exit lowers the belonging return of every other household. The formula $1/(1-G')$ at the equilibrium slope predicts a multiplier of {f1(1/(1-R['slope0']))} for a small shock, so the same slope the bound of the first result constrains is the slope that sets the size of the second; the twenty-point shock examined is large enough that curvature pulls the realised multiplier below that linear prediction, and Section 6.1 reports both. A map flat enough to rule out coordination traps by only a modest margin is a map that can still amplify a large policy shock several times over, and the two statements are one statement read at two scales.")
edits.append((old_i2, new_i2))

old_i3 = "Fourth, the contrast that makes the policy point usable. Raising the lower-education group's agency to the population mean, an empowerment policy in the SAGE sense, raises equilibrium participation from 35 to 46 percent and narrows the education gap, without any fiscal instrument at all. A participation tax credit, modelled at the real rebate rates of the United Kingdom's Gift Aid and France's charitable-donations deduction, does the same from the other direction and far more cheaply: Gift Aid's 25 percent rebate lifts participation from 35 to 85 percent at a sixth of the work subsidy's fiscal cost. Because such credits are claimed unevenly, I add a take-up gradient, and it turns the distributional verdict. At full take-up the credit is equalising, cutting the ratio of higher- to lower-group participation from 1.65 to 1.14; at half take-up it is roughly neutral; and when the lower group claims at only a quarter of the higher group's rate the ratio rises to 1.50, so the instrument becomes disequalising while remaining expansionary. Take-up is therefore not a second-order caveat on this policy but the thing that decides who it is for. Policies from the same pro-work family therefore have opposite effects on the social fabric: subsidising hours raises the price of time and unravels participation, while empowering people or paying them for the act of joining crowds it in. An evaluation framework that does not carry the social dimension cannot tell these policies apart on the margin where they differ most."
new_i3 = (f"Fourth, the contrast that makes the policy point usable. Raising the lower-education group's agency to the population mean, an empowerment policy in the SAGE sense, raises equilibrium participation from {f1(pct(r0))} to {f1(pct(R['r_emp']))} percent and narrows the education gap, without any fiscal instrument at all. A participation tax credit, modelled at the real rebate rates of the United Kingdom's Gift Aid and France's charitable-donations deduction, does the same from the other direction and far more cheaply: Gift Aid's 25 percent rebate lifts participation from {f1(pct(r0))} to {f1(pct(R['cred_25_100_r']))} percent at a fraction of the work subsidy's fiscal cost. Because such credits are claimed unevenly, I add a take-up gradient, and the natural worry does not materialise: the credit stays equalising at every take-up rate examined. The ratio of higher- to lower-group participation is {f2(ratio0)} at baseline; full take-up cuts it to {f2(R['cred_25_100_hi']/R['cred_25_100_lo'])}, and even at a quarter take-up, where the lower group claims the rebate at only a fraction of the higher group's rate, it falls to {f2(R['cred_25_25_hi']/R['cred_25_25_lo'])}, still below baseline. Take-up disciplines how much the credit equalises, not whether it does. Policies from the same pro-work family therefore have opposite effects on the social fabric: subsidising hours raises the price of time and unravels participation, while empowering people or paying them for the act of joining crowds it in. An evaluation framework that does not carry the social dimension cannot tell these policies apart on the margin where they differ most.")
edits.append((old_i3, new_i3))

# ------------------------------------------------------------- calibration --
old_cal = "I calibrate $(\\kappa, \\sigma_m)$ to the two INSEE participation moments, group rates of 0.25 and 0.45 at a stable equilibrium, with $\\omega = 0.30$ held at its central value and swept in robustness. The best fit is $\\kappa = 10.75$, $\\sigma_m = 0.750$, at which the economy has a unique stable equilibrium with aggregate participation 0.353 and group rates 0.267 and 0.439 (Figure \\ref{fig:gradient})."
new_cal = (f"I calibrate $(\\kappa, \\sigma_m)$ to the two INSEE participation moments, group rates of 0.25 and 0.45 at a stable equilibrium, with $\\omega = 0.30$ held at its central value and swept in robustness. The best fit is $\\kappa = {f2(R['kappa'])}$, $\\sigma_m = {f3(R['sigma'])}$, at which the economy has a unique stable equilibrium with aggregate participation {f3(r0)} and group rates {f3(lo)} and {f3(hi)} (Figure \\ref{{fig:gradient}}).")
edits.append((old_cal, new_cal))

# ------------------------------------------------------------- proposition --
old_prop = "At the calibrated equilibrium the aggregate rate is $r = 0.353$, group rates are $0.267$ and $0.439$, and $\\omega = 0.30$. The complementarity factor is $1.280$ and the density term $0.361$, so $\\bar\\sigma = 0.463$. The dispersion the participation data require is $\\sigma_m = 0.750$, which exceeds the bound by sixty percent. Multiplicity is ruled out, and not marginally: the economy would need its belonging tastes compressed by well over a third before coordination traps became possible at all."
new_prop = (f"At the calibrated equilibrium the aggregate rate is $r = {f3(r0)}$, group rates are ${f3(lo)}$ and ${f3(hi)}$, and $\\omega = 0.30$. The complementarity factor is ${f3(R['comp'])}$ and the density term ${f3(R['dens'])}$, so $\\bar\\sigma = {f3(R['sigbar'])}$. The dispersion the participation data require is $\\sigma_m = {f3(R['sigma'])}$, which exceeds the bound by about ten percent. Multiplicity is ruled out, though not by a wide margin: the economy would need its belonging tastes compressed by roughly a tenth before coordination traps became possible at all, which is why Section 5.3 checks how robust that margin is to the one parameter the data do not pin down.")
edits.append((old_prop, new_prop))

# ------------------------------------------------------------ omega table ---
old_tab = "0.15 & 13.00 & 0.740 & 0.284 / 0.402 & 0.932 & 0.699 & 1.06 \\\\\n0.30 & 10.75 & 0.740 & 0.299 / 0.417 & 0.626 & 0.469 & 1.58 \\\\\n0.50 & 8.00 & 0.410 & 0.233 / 0.434 & 0.615 & 0.262 & 1.56 \\\\"
def row(w):
    d = om[w]
    return f"{w:.2f} & {d['kappa']:.2f} & {d['sigma']:.3f} & {d['lo']:.3f} / {d['hi']:.3f} & {d['slope']:.3f} & {d['sigbar']:.3f} & {d['ratio']:.2f} \\\\"
new_tab = "\n".join(row(w) for w in (0.15, 0.30, 0.50))
edits.append((old_tab, new_tab))

old_omega_p1 = "Three things follow, and the second is a caution rather than a comfort. First, the verdict is robust: the ratio exceeds one at every $\\omega$, so multiplicity is ruled out however the private share is set, and the direct numerical scan agrees, putting the fold at $\\sigma_m \\le 0.68$, $0.30$ and $0.16$ respectively, always inside the bound.\n\nSecond, the margin is not robust. At $\\omega = 0.15$ the ratio is 1.06 and the map slope is 0.932, so the economy sits barely outside the coordination region and close to a fold. A reader who believes participation is almost entirely a social payoff should read this paper as saying France is near the edge, not far from it. That is the honest statement of what the result depends on, and it identifies $\\omega$ as the quantity worth measuring next: the difference between a slope of 0.62 and one of 0.93 is the difference between a policy multiplier of two and a half and one of fifteen, which matters far more for policy than the multiplicity verdict does."
new_omega_p1 = (
 f"Three things follow, and none of them is a comfort. First, the verdict is robust: the ratio exceeds one at every $\\omega$ examined, so multiplicity is ruled out however the private share is set, and the direct numerical scan agrees, putting the fold at $\\sigma_m \\le {om[0.15]['frontier']:.2f}$, ${om[0.30]['frontier']:.2f}$ and ${om[0.50]['frontier']:.2f}$ respectively, always inside the bound.\n\n"
 f"Second, the margin is thin across most of the range examined, and the central calibration is one of the thin points. At $\\omega = 0.15$ the ratio is {om[0.15]['ratio']:.2f} with map slope {om[0.15]['slope']:.3f}; at the central $\\omega = 0.30$ the ratio is {om[0.30]['ratio']:.2f} with slope {om[0.30]['slope']:.3f}, essentially the same margin. Only at $\\omega = 0.50$ does the economy move comfortably away from the edge, ratio {om[0.50]['ratio']:.2f} and slope {om[0.50]['slope']:.3f}. A reader who believes participation is anywhere below about half a private payoff should read this paper as saying France sits close to the coordination boundary, not far from it. That is the honest statement of what the result depends on, and it identifies $\\omega$ as the quantity worth measuring next: the difference between a slope of {om[0.50]['slope']:.2f} and one of {om[0.30]['slope']:.2f} is the difference between a policy multiplier of {1/(1-om[0.50]['slope']):.1f} and one of {1/(1-om[0.30]['slope']):.0f}, which matters far more for policy than the multiplicity verdict does."
)
edits.append((old_omega_p1, new_omega_p1))

old_omega_p2 = "Third, the fit improves markedly at the high private share. At $\\omega = 0.50$ the calibrated group rates are 0.233 and 0.434 against targets of 0.25 and 0.45, so the gradient shortfall reported in Section 3 is a consequence of holding $\\omega$ at 0.30 rather than a structural limit of the two-cell model. The verdict at that better-fitting point is the same, ratio 1.56 against 1.58, and so is the map slope, so nothing in Section 6 turns on the choice between these two; what the comparison buys is the knowledge that the model can hit the gradient, not a different answer. Table \\ref{tab:omega}'s middle row also serves as a check on the calibration procedure itself, since it repeats the headline calibration through a coarser search and returns $\\kappa^* = 10.75$ and $\\sigma_m^* = 0.740$ against the headline $0.750$."
new_omega_p2 = (f"Third, the fit at the central calibration is already close: group rates {f3(lo)} and {f3(hi)} against targets of 0.25 and 0.45, so the gradient shortfall is modest rather than structural. Fit does not improve monotonically with $\\omega$ in this sweep; what moves is the margin, and Section 6 states the policy magnitudes with that dependence in view rather than treating $\\omega = 0.30$ as settled.")
edits.append((old_omega_p2, new_omega_p2))

